INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 1, 0, 1, "あたしだって\nやるときはやるよ！", 24, 10040, "リン", 24001, 102601, 0, 0, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 1, 0, 1, "ふぅ…\nこれであたしの仕事は\n終わりだね", 24, 10040, "リン", 24002, 102601, 0, 1, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 1, 0, 1, "終わった終わった\n一人でもなんとか\nなるもんだね", 24, 10040, "リン", 24003, 102601, 0, 2, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 2, 0, 2, "やったね！\nこれでようやく\nサボれるよ…", 24, 10040, "リン", 24004, 102601, 0, 3, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 1, 0, 1, "チーズが欲しいなら\nきちんと働いて\n買いに来なよ", 24, 10040, "リン", 24005, 102601, 0, 4, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 2, 0, 2, "あたしを敵に回した\n恐ろしさ\n思い知ったか！", 24, 10040, "リン", 24006, 102601, 0, 5, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 2, 0, 2, "あたしも意外と\nやるもんでしょ？", 24, 10040, "リン", 24007, 102601, 0, 6, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 4, 0, 4, "疲れた…\nねずみの逃げ足\n速すぎるよ…", 24, 10040, "リン", 24008, 102601, 0, 7, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 4, 0, 4, "このままじゃ\nまっひ～に\n叱られちゃうよ", 24, 10040, "リン", 24009, 102601, 0, 8, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 4, 0, 4, "まじめに\nやったんだけどな…\n悔しいな～", 24, 10040, "リン", 24010, 102601, 0, 9, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 4, 0, 4, "やられた…\nねずみって意外と\nてごわいね", 24, 10040, "リン", 24011, 102601, 0, 10, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 4, 0, 4, "おのれ～\nあたしのチーズを\n盗みやがって～！", 24, 10040, "リン", 24012, 102601, 0, 11, 0, "2030/12/17 14:59:59");
INSERT INTO `v1_7d90a6bc458265129794e0bd507317a2a880c447185cf0cce84238883128d363` VALUES ("2020/04/30 12:00:00", 1, 0, 4, "疲れた…\nけど、次こそは\n守り抜くよ…", 24, 10040, "リン", 24013, 102601, 0, 12, 1.81, "2030/12/17 14:59:59");
